begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
insert into auth.users(id,email,is_anonymous) values('fd030000-0000-4000-8000-000000000001','stove-transport@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','fd030000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable Stove internal transport','Owner');
reset role;
do $$declare t uuid:=app_private.current_tenant_id();d date:=(now() at time zone 'Asia/Dhaka')::date;w uuid;i uuid;k uuid;v uuid;driver uuid;helper uuid;p uuid;s uuid;tr jsonb;r jsonb;before jsonb;begin
 select wallet_id into w from public.get_payment_wallets() where type='cash';select type_id into k from public.get_stove_product_types() limit 1;
 i:=(public.save_stove_product(jsonb_build_object('name','Transported stove','type_id',k),gen_random_uuid())->>'item_id')::uuid;
 driver:=(public.save_employee(jsonb_build_object('name','Driver zero base','employee_type_name','Driver','business_unit','truck_business','phones',jsonb_build_array(jsonb_build_object('phone','01700000981','is_primary',true)),'terms',jsonb_build_object('monthly_salary',0,'effective_from',d,'is_active',true)),gen_random_uuid())->>'employee_id')::uuid;
 helper:=(public.save_employee(jsonb_build_object('name','Helper zero base','employee_type_name','Helper','business_unit','truck_business','phones',jsonb_build_array(jsonb_build_object('phone','01700000982','is_primary',true)),'terms',jsonb_build_object('monthly_salary',0,'effective_from',d,'is_active',true)),gen_random_uuid())->>'employee_id')::uuid;
 v:=(public.save_vehicle(jsonb_build_object('name','Stove transport truck','serial_no','STOVE-T1','capacity',100,'book_value',100000,'funding','opening','driver_employee_id',driver,'helper_employee_id',helper),gen_random_uuid())->>'vehicle_id')::uuid;
 p:=(public.create_purchase(jsonb_build_object('request_id',gen_random_uuid(),'business_category','stove','supplier_name','Direct supplier','items',jsonb_build_array(jsonb_build_object('item_id',i,'type','package','quantity',10,'unit_price',100))))->>'purchase_id')::uuid;
 perform public.receive_purchase(p,1,d);
 p:=(public.create_purchase(jsonb_build_object('request_id',gen_random_uuid(),'business_category','stove','supplier_name','Delivered supplier','vehicle_id',v,'transport_cost',1000,'items',jsonb_build_array(jsonb_build_object('item_id',i,'type','package','quantity',10,'unit_price',300))))->>'purchase_id')::uuid;
 begin perform public.receive_purchase(p,1,d);raise exception 'FAIL: uncharged transport bypassed dispatch';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;
 perform public.dispatch_purchase(p,1,d);perform public.dispatch_purchase(p,1,d);perform public.receive_purchase(p,2,d);
 select public.get_transit(transit_id) into tr from public.transits where tenant_id=t and purchase_id=p;
 perform public.transition_transit((tr->>'transit_id')::uuid,'complete',(tr->>'revision')::integer);
 perform pg_temp.assert((select count(*)=2 from public.wallet_transactions where tenant_id=t and reference_id=p and type like 'internal_transport_%'),'Dispatch retries and completion charge Stove transport exactly once');
 insert into public.price_books(tenant_id,item_id,price_type,customer_tier,price,effective_from) values(t,i,'package','retail',500,now()-interval '1 day');
 s:=(public.create_pos_sale('01700000983','Stove delivery buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',i,'type','package','quantity',12,'unit_price',500)),null,gen_random_uuid(),'[]',null)->>'sale_id')::uuid;
 perform pg_temp.assert((select sum(amount)=1800 and sum(consolidated_amount)=1600 from public.accounting_lines where tenant_id=t and account='cogs'),'Independent Stove FIFO consumes 10*100 plus 2*(300+100 internal), eliminating internal 200');
 perform pg_temp.assert((select sum(remaining_internal_value)=800 from app_private.fifo_layers where tenant_id=t and item_id=i),'Eight delivered Stove units retain exactly 800 internal overhead');
 r:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d));
 perform pg_temp.assert((r->'totals'->>'profit')::numeric=4400 and (r->'period_values'->>'stock_acquisitions')::numeric=4000,'Consolidated Stove profit/acquisitions exclude internal transport');
 begin perform public.initiate_purchase_cancellation(p,3,'CANCEL',gen_random_uuid());raise exception 'FAIL: consumed received stock cancelled';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;perform pg_temp.assert(lower(sqlerrm) like '%consum%','Expected original batch guard');end;
 perform public.reverse_sale(s,'Original Stove layer return','CANCEL',gen_random_uuid());
 perform public.initiate_purchase_cancellation(p,3,'CANCEL',gen_random_uuid());
 perform pg_temp.assert((select count(*)=2 from public.wallet_transactions where tenant_id=t and reference_id=p and type like 'internal_transport_%'),'Returning delivered goods does not invent a refund for performed transportation');
 perform pg_temp.assert((select status='completed' from public.transits where tenant_id=t and purchase_id=p),'Delivered journey history remains completed after goods return');
 perform pg_temp.assert((select sum(remaining_internal_value)=0 from app_private.fifo_layers where tenant_id=t and item_id=i),'Returned goods release their original internal FIFO carrying value');
 perform pg_temp.assert((select sum(amount)=1000 and sum(consolidated_amount)=0 from public.accounting_lines where tenant_id=t and account='inventory_loss'),'Performed transport becomes buyer return cost, eliminated on consolidation');
 r:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d));perform pg_temp.assert((r->'totals'->>'profit')::numeric=0,'Organization profit is unchanged by internal service plus returned supplier goods');
 select business_balances into before from public.wallets where tenant_id=t and wallet_id=w;
 p:=(public.create_purchase(jsonb_build_object('request_id',gen_random_uuid(),'business_category','stove','supplier_name','Undelivered supplier','vehicle_id',v,'transport_cost',200,'items',jsonb_build_array(jsonb_build_object('item_id',i,'type','package','quantity',1,'unit_price',100))))->>'purchase_id')::uuid;
 perform public.dispatch_purchase(p,1,d);perform public.initiate_purchase_cancellation(p,2,'CANCEL',gen_random_uuid());
 perform pg_temp.assert((select business_balances=before from public.wallets where tenant_id=t and wallet_id=w),'Unreceived Stove cancellation returns its exact original business cash portions');
end $$;
set constraints all immediate;
select 'PASS: Stove direct/internal delivery, transit completion, independent FIFO, partial issue/return, performed-service preservation and unreceived cancellation';
rollback;
